import os
import httpx
import json
from abc import ABC, abstractmethod
from typing import Dict, Any
from .core_types import TokenUsage

# Pricing per 1M tokens (Input/Output) in USD - for OKR-1
PRICING = {
    "gpt-4-turbo": (10.00, 30.00),
    "gpt-3.5-turbo": (0.50, 1.50), # Added for completeness, common model
    "claude-3-haiku-20240307": (0.25, 1.25),
    "claude-3-sonnet-20240229": (3.00, 15.00), # Added for completeness
    "gemini-1.5-flash": (0.35, 0.53), # Based on context size pricing, simplified
    "gemini-1.5-pro": (3.50, 10.50), # Added for completeness
    "llama3": (0.0, 0.0), # Local model
}

class LLMProvider(ABC):
    def __init__(self, model: str):
        self.model = model
        self.provider_name = self.__class__.__name__.lower().replace("provider", "")

    @abstractmethod
    def call(self, system_prompt: str, user_prompt: str) -> (str, int, int):
        pass

    def get_cost(self, in_tokens: int, out_tokens: int) -> float:
        in_price, out_price = PRICING.get(self.model, (0.0, 0.0))
        cost = ((in_tokens / 1_000_000) * in_price) + ((out_tokens / 1_000_000) * out_price)
        return cost

class OllamaProvider(LLMProvider):
    def call(self, system_prompt: str, user_prompt: str) -> (str, int, int):
        host = os.getenv("OLLAMA_HOST", "http://localhost:11434")
        body = {
            "model": self.model,
            "stream": False,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt}
            ]
        }
        with httpx.Client(timeout=60.0) as client:
            response = client.post(f"{host}/api/chat", json=body) # Use /api/chat for better token estimation
            response.raise_for_status()
            data = response.json()

            # Ollama provides prompt_eval_count and eval_count for chat API
            in_tokens = data.get('prompt_eval_count', 0)
            out_tokens = data.get('eval_count', 0)

            # Fallback to estimation if counts are not present (e.g., older Ollama versions or /api/generate)
            if in_tokens == 0 and out_tokens == 0:
                in_tokens = (len(system_prompt) + len(user_prompt)) // 4
                out_tokens = len(data['message']['content']) // 4

            return data['message']['content'], in_tokens, out_tokens

class OpenAIProvider(LLMProvider):
    def call(self, system_prompt: str, user_prompt: str) -> (str, int, int):
        api_key = os.getenv("OPENAI_API_KEY")
        if not api_key:
            raise ValueError("OPENAI_API_KEY environment variable not set.")

        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        body = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt}
            ],
            "temperature": 0.7,
        }

        with httpx.Client(timeout=60.0) as client:
            response = client.post("https://api.openai.com/v1/chat/completions", headers=headers, json=body)
            response.raise_for_status()
            data = response.json()

            content = data['choices'][0]['message']['content']
            in_tokens = data['usage']['prompt_tokens']
            out_tokens = data['usage']['completion_tokens']

            return content, in_tokens, out_tokens

class AnthropicProvider(LLMProvider):
    def call(self, system_prompt: str, user_prompt: str) -> (str, int, int):
        api_key = os.getenv("ANTHROPIC_API_KEY")
        if not api_key:
            raise ValueError("ANTHROPIC_API_KEY environment variable not set.")

        headers = {
            "x-api-key": api_key,
            "anthropic-version": "2023-06-01", # Required API version
            "Content-Type": "application/json",
        }
        body = {
            "model": self.model,
            "max_tokens": 4096, # Anthropic requires max_tokens
            "system": system_prompt,
            "messages": [
                {"role": "user", "content": user_prompt}
            ],
            "temperature": 0.7,
        }

        with httpx.Client(timeout=60.0) as client:
            response = client.post("https://api.anthropic.com/v1/messages", headers=headers, json=body)
            response.raise_for_status()
            data = response.json()

            content = data['content'][0]['text']
            in_tokens = data['usage']['input_tokens']
            out_tokens = data['usage']['output_tokens']

            return content, in_tokens, out_tokens

class GeminiProvider(LLMProvider):
    def call(self, system_prompt: str, user_prompt: str) -> (str, int, int):
        api_key = os.getenv("GEMINI_API_KEY")
        if not api_key:
            raise ValueError("GEMINI_API_KEY environment variable not set.")

        headers = {
            "Content-Type": "application/json",
        }
        body = {
            "contents": [
                {"role": "user", "parts": [{"text": system_prompt + "\n" + user_prompt}]}
            ],
            "generationConfig": {
                "temperature": 0.7,
                "maxOutputTokens": 4096,
            }
        }

        # Gemini API endpoint structure: https://generativelanguage.googleapis.com/v1beta/models/MODEL_NAME:generateContent?key=YOUR_API_KEY
        endpoint = f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:generateContent?key={api_key}"

        with httpx.Client(timeout=60.0) as client:
            response = client.post(endpoint, headers=headers, json=body)
            response.raise_for_status()
            data = response.json()

            content = data['candidates'][0]['content']['parts'][0]['text']

            # Gemini API does not directly return token counts in the generateContent response.
            # We need to make a separate countTokens call.
            count_tokens_body = {
                "contents": [
                    {"role": "user", "parts": [{"text": system_prompt + "\n" + user_prompt}]}
                ]
            }
            count_tokens_endpoint = f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:countTokens?key={api_key}"
            count_response = client.post(count_tokens_endpoint, headers=headers, json=count_tokens_body)
            count_response.raise_for_status()
            count_data = count_response.json()
            in_tokens = count_data.get('totalTokens', 0)

            # For output tokens, we'll count the generated content
            out_tokens = len(content) // 4 # Approximation, as countTokens doesn't apply to output

            return content, in_tokens, out_tokens


def get_provider(model: str) -> LLMProvider:
    provider_name = os.getenv("LLM_PROVIDER", "ollama").lower()

    # Determine the actual model to use based on provider-specific env vars or default to passed model
    if provider_name == "ollama":
        actual_model = os.getenv("OLLAMA_MODEL", model)
        return OllamaProvider(model=actual_model)
    elif provider_name == "openai":
        actual_model = os.getenv("OPENAI_MODEL", model)
        return OpenAIProvider(model=actual_model)
    elif provider_name == "anthropic":
        actual_model = os.getenv("ANTHROPIC_MODEL", model)
        return AnthropicProvider(model=actual_model)
    elif provider_name == "gemini":
        actual_model = os.getenv("GEMINI_MODEL", model)
        return GeminiProvider(model=actual_model)
    else:
        raise ValueError(f"Unknown LLM_PROVIDER: {provider_name}")
